        }

        .product-grid,
        .deal-grid,
        .editorial-grid,
        .editorial-card.featured,
        .promo-band,
        .newsletter-form {
          grid-template-columns: 1fr;
        }

        .hero-metrics {
          grid-template-columns: 1fr;
        }
      }
