       }

       html {
         scroll-behavior: smooth;
       }

       body {
         margin: 0;
         background:
           radial-gradient(circle at top left, #ffe3b1 0, transparent 34rem),
           linear-gradient(180deg, var(--color-bg) 0%, #fffdf9 50%, #f8f1e8 100%);
         color: var(--color-text);
         line-height: 1.5;
       }

       img,
       svg {
         display: block;
         max-width: 100%;
       }

       a {
         color: var(--color-link);
         text-decoration-thickness: 0.08em;
         text-underline-offset: 0.18em;
       }

       a:hover {
         color: var(--color-link-hover);
       }

       button,
       input {
         font: inherit;
       }

       :focus-visible {
         outline: 3px solid var(--color-focus);
         outline-offset: 4px;
       }

       .skip-link {
         background: var(--color-text);
         border-radius: 999px;
         color: var(--color-surface-strong);
         font-weight: 800;
         left: 1rem;
         padding: 0.75rem 1rem;
         position: absolute;
         top: 1rem;
         transform: translateY(-160%);
         transition: transform 160ms ease;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       .visually-hidden {
         clip: rect(0 0 0 0);
         clip-path: inset(50%);
         height: 1px;
         overflow: hidden;
         position: absolute;
         white-space: nowrap;
         width: 1px;
       }

       .page-shell {
         margin: 0 auto;
         max-width: var(--container);
         padding: 0 1.25rem;
       }

       .site-header {
         padding: 1rem 0;
       }

       .header-inner {
         align-items: center;
         background: #fffaf2e8;
         border: 1px solid var(--color-border);
         border-radius: 999px;
         box-shadow: var(--shadow-soft);
         display: flex;
         gap: 1rem;
         justify-content: space-between;
         padding: 0.75rem 0.9rem 0.75rem 1.15rem;
       }

       .brand {
         align-items: center;
         color: var(--color-text);
         display: inline-flex;
         font-weight: 900;
         gap: 0.65rem;
         letter-spacing: -0.03em;
         text-decoration: none;
       }

       .brand-mark {
         align-items: center;
         background: var(--color-text);
         border-radius: 50%;
         color: var(--color-accent);
         display: inline-flex;
         font-size: 0.9rem;
         height: 2.25rem;
         justify-content: center;
         letter-spacing: 0;
         width: 2.25rem;
       }

       .primary-nav ul,
       .footer-nav ul {
         display: flex;
         gap: 0.35rem;
         list-style: none;
         margin: 0;
         padding: 0;
       }

       .primary-nav a,
       .footer-nav a {
         border-radius: 999px;
         color: var(--color-text);
         display: inline-flex;
         font-weight: 750;
         padding: 0.65rem 0.85rem;
         text-decoration: none;
       }

       .primary-nav a:hover,
       .footer-nav a:hover {
         background: var(--color-accent-soft);
       }

       .header-actions {
         align-items: center;
         display: flex;
         gap: 0.6rem;
       }

       .cart-status {
         color: var(--color-muted-text);
         font-size: 0.92rem;
         font-weight: 750;
         white-space: nowrap;
       }

       .button,
       .text-button {
         align-items: center;
         border: 2px solid transparent;
         border-radius: 999px;
         cursor: pointer;
         display: inline-flex;
         font-weight: 850;
         gap: 0.5rem;
         justify-content: center;
         min-height: 2.75rem;
         padding: 0.72rem 1rem;
         text-decoration: none;
       }

       .button {
