      }

      .spotlight-content p {
        color: #efe2cf;
      }

      .section {
        padding: 3.75rem 0;
      }

      .section-header {
        align-items: end;
        display: flex;
        gap: 1rem;
        justify-content: space-between;
        margin-bottom: 1.5rem;
      }

      .section-header p {
        color: var(--color-muted-text);
        margin: 0.65rem 0 0;
        max-width: 42rem;
      }

      .grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .deal-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .editorial-grid {
        grid-template-columns: 1.3fr 0.85fr 0.85fr;
      }

      .card {
        background: var(--color-surface-strong);
        border: 1px solid var(--color-border);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow-soft);
        overflow: hidden;
      }

      .product-card {
        display: flex;
        flex-direction: column;
      }

      .product-visual,
      .deal-visual,
      .editorial-visual {
        align-items: center;
        background: var(--visual-bg, var(--color-accent-soft));
        display: flex;
        justify-content: center;
        min-height: 190px;
      }

      .product-visual svg,
      .deal-visual svg {
        color: var(--visual-ink, var(--color-text));
        height: 7.5rem;
        width: 7.5rem;
      }

      .product-body,
      .deal-body,
      .editorial-body {
        display: flex;
        flex: 1;
        flex-direction: column;
        padding: 1.1rem;
      }

      .product-title-link,
      .editorial-title-link {
        color: var(--color-text);
        text-decoration: none;
      }

      .product-title-link:hover,
      .editorial-title-link:hover {
        color: var(--color-link);
        text-decoration: underline;
        text-decoration-thickness: 0.08em;
      }

      .product-meta,
      .deal-meta,
      .article-meta {
        color: var(--color-muted-text);
        font-size: 0.92rem;
        margin: 0.55rem 0 0;
      }

      .price-row {
        align-items: baseline;
        display: flex;
        gap: 0.55rem;
        margin: 1rem 0;
      }

      .price {
        font-size: 1.35rem;
        font-weight: 900;
      }

      .original-price {
        color: var(--color-muted-text);
        text-decoration: line-through;
      }

      .tag {
        align-self: flex-start;
        background: var(--color-accent-soft);
        border: 1px solid #d6a761;
        border-radius: 999px;
        color: #50310f;
        font-size: 0.8rem;
        font-weight: 850;
        margin-bottom: 0.75rem;
        padding: 0.32rem 0.6rem;
      }

      .product-card .button {
        margin-top: auto;
        width: 100%;
      }

      .deal-card {
        min-height: 330px;
      }

      .deal-visual {
        min-height: 150px;
      }

      .deal-percent {
        font-size: clamp(3rem, 8vw, 5.5rem);
        font-weight: 950;
        letter-spacing: -0.08em;
        line-height: 0.9;
      }

      .deal-body p,
      .editorial-body p {
        color: var(--color-muted-text);
      }

      .editorial-card.featured {
        display: grid;
        grid-template-columns: 0.95fr 1fr;
      }

      .editorial-card.featured .editorial-visual {
        min-height: 100%;
      }

      .editorial-visual {
        min-height: 210px;
        overflow: hidden;
      }

      .editorial-visual.pattern-lines {
        background:
          linear-gradient(135deg, #1f1b16 0 6%, transparent 6% 12%, #1f1b16 12% 18%, transparent 18% 100%),
          #f3c66b;
        background-size: 2.5rem 2.5rem;
      }

      .editorial-visual.pattern-circles {
        background:
          radial-gradient(circle at 30% 30%, #fffaf2 0 1.1rem, transparent 1.15rem),
          radial-gradient(circle at 70% 60%, #1f1b16 0 2.1rem, transparent 2.2rem),
          #c97d4b;
      }

      .editorial-visual.pattern-waves {
        background:
          radial-gradient(ellipse at 30% 0%, transparent 0 42%, #fffaf2 43% 46%, transparent 47%),
          radial-gradient(ellipse at 70% 100%, transparent 0 42%, #1f1b16 43% 46%, transparent 47%),
          #8fb19c;
        background-size: 7rem 7rem;
      }

      .promo-band {
        align-items: center;
        background: var(--color-text);
        border-radius: var(--radius-xl);
        color: var(--color-surface-strong);
        display: grid;
        gap: 1rem;
        grid-template-columns: 1fr auto;
        margin: 2rem 0;
        padding: clamp(1.5rem, 4vw, 2.4rem);
      }

      .promo-band h2 {
        font-size: clamp(1.8rem, 4vw, 3rem);
      }

      .promo-band p {
        color: #efe2cf;
        margin: 0.55rem 0 0;
        max-width: 42rem;
      }

      .newsletter {
        background: var(--color-surface-strong);
        border: 1px solid var(--color-border);
        border-radius: var(--radius-xl);
        display: grid;
        gap: 1.25rem;
        grid-template-columns: 1fr 0.9fr;
        margin: 2rem 0 0;
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .newsletter p {
        color: var(--color-muted-text);
      }

      .newsletter-form {
        align-items: end;
        display: grid;
        gap: 0.75rem;
        grid-template-columns: 1fr auto;
      }

      .field label {
        display: block;
        font-weight: 850;
        margin-bottom: 0.45rem;
      }

      .field input {
        background: #fffdf9;
        border: 2px solid var(--color-border);
        border-radius: 999px;
        color: var(--color-text);
        min-height: 3rem;
        padding: 0.7rem 1rem;
        width: 100%;
      }

      .help-text {
        color: var(--color-muted-text);
        font-size: 0.9rem;
        margin: 0.45rem 0 0;
      }

      .form-message {
        grid-column: 1 / -1;
      }

      .site-footer {
        border-top: 1px solid var(--color-border);
        margin-top: 3rem;
        padding: 2rem 0;
      }

      .footer-inner {
        align-items: center;
        display: flex;
        gap: 1rem;
        justify-content: space-between;
      }

      .footer-note {
        color: var(--color-muted-text);
        margin: 0;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
        }
      }

      @media (forced-colors: active) {
        .button,
        .text-button,
        .card,
        .hero-panel,
        .spotlight-card,
        .header-inner,
        .newsletter,
        .promo-band {
          border: 2px solid ButtonBorder;
          box-shadow: none;
        }

        .button,
        .button.secondary {
          background: ButtonFace;
          color: ButtonText;
        }

        .brand-mark {
          border: 1px solid ButtonBorder;
        }
      }

      @media (max-width: 980px) {
        .hero,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .hero-panel,
        .spotlight-card {
          min-height: auto;
        }

        .product-grid,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .editorial-card.featured {
          grid-column: 1 / -1;
        }
      }

      @media (max-width: 720px) {
        .header-inner,
        .footer-inner,
        .section-header,
        .promo-band {
          align-items: stretch;
          border-radius: var(--radius-lg);
          flex-direction: column;
        }

        .header-inner {
          display: grid;
        }

        .primary-nav ul,
        .footer-nav ul,
        .header-actions,
        .hero-actions {
          flex-wrap: wrap;
        }

        .primary-nav a,
        .footer-nav a {
          padding-inline: 0.65rem;
        }

        .section-header {
          display: block;
        }

        .section-header .text-button {
          margin-top: 1rem;
        }

        .product-grid,
        .deal-grid,
        .editorial-grid,
        .editorial-card.featured,
        .promo-band,
        .newsletter-form {
          grid-template-columns: 1fr;
        }

        .hero-metrics {
          grid-template-columns: 1fr;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="app" aria-live="off"></div>
    <script>
      const store = {
        navItems: [
          { label: "New arrivals", href: "#featured" },
          { label: "Deals", href: "#deals" },
          { label: "Journal", href: "#editorial" },
          { label: "Membership", href: "#membership" }
        ],
        products: [
          {
            name: "CloudKnit Lounge Set",
            category: "Apparel",
            price: "$88",
            detail: "Organic cotton blend in oat, sage, and espresso.",
            tag: "Best seller",
            href: "#cloudknit",
            color: "#f4d090",
            ink: "#6b3f25",
            shape: "shirt"
          },
          {
            name: "Aura Table Lamp",
            category: "Home",
            price: "$64",
            detail: "Warm dimming ceramic lamp for desks and nightstands.",
            tag: "New",
            href: "#aura-lamp",
            color: "#d9e7d8",
            ink: "#315441",
            shape: "lamp"
          },
          {
            name: "Transit Weekender",
            category: "Travel",
            price: "$124",
            detail: "Water-resistant recycled canvas with shoe storage.",
            tag: "Top rated",
            href: "#transit-weekender",
            color: "#d8c6f2",
            ink: "#4b3478",
            shape: "bag"
          },
          {
            name: "Daily Ritual Kit",
            category: "Wellness",
            price: "$42",
            detail: "Body wash, hand cream, and mineral soak trio.",
            tag: "Gift ready",
            href: "#ritual-kit",
            color: "#ffd9c7",
            ink: "#884328",
            shape: "bottle"
          }
        ],
        deals: [
          {
            title: "Refresh your closet",
            percent: "30%",
            detail: "Save on breathable layers, denim, and easy weekend staples.",
            cta: "Shop apparel deals",
            href: "#apparel-deals",
            color: "#f2b84b"
          },
          {
            title: "Home reset event",
            percent: "25%",
            detail: "Lighting, bedding, and counter-ready storage are marked down.",
            cta: "Shop home deals",
            href: "#home-deals",
            color: "#a9c8b1"
          },
          {
            title: "Travel pairs",
            percent: "2x",
            detail: "Buy any bag and get double member points through Sunday.",
            cta: "Explore travel picks",
            href: "#travel-deals",
            color: "#cdb7ea"
          }
        ],
        articles: [
          {
            title: "The 10-piece capsule for softer mornings",
            meta: "Style guide · 6 min read",
            detail: "Build a reliable rotation from texture, tone, and practical layers.",
            href: "#capsule-guide",
            pattern: "pattern-lines",
            featured: true
          },
          {
            title: "How to light a small space",
            meta: "Home edit · 4 min read",
            detail: "Three easy zones that make an apartment feel layered and calm.",
            href: "#lighting-guide",
            pattern: "pattern-circles"
          },
          {
            title: "Gift notes that feel personal",
            meta: "Editors' picks · 3 min read",
            detail: "Thoughtful pairings for hosts, new parents, and frequent flyers.",
            href: "#gift-notes",
            pattern: "pattern-waves"
          }
        ]
      };

      const iconPaths = {
        shirt: '<path d="M34 22 48 14h16l14 8-7 15-8-4v57H49V33l-8 4-7-15Z" fill="currentColor" opacity=".22"/><path d="M48 14c3 8 8 12 16 12s13-4 16-12" fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round"/><path d="M34 22 48 14h16l14 8-7 15-8-4v57H49V33l-8 4-7-15Z" fill="none" stroke="currentColor" stroke-width="7" stroke-linejoin="round"/>',
        lamp: '<path d="M45 20h38l8 35H37l8-35Z" fill="currentColor" opacity=".22"/><path d="M45 20h38l8 35H37l8-35Z" fill="none" stroke="currentColor" stroke-width="7" stroke-linejoin="round"/><path d="M64 55v35M48 90h32" stroke="currentColor" stroke-width="7" stroke-linecap="round"/>',
        bag: '<path d="M34 40h60l-5 54H39L34 40Z" fill="currentColor" opacity=".22"/><path d="M34 40h60l-5 54H39L34 40Z" fill="none" stroke="currentColor" stroke-width="7" stroke-linejoin="round"/><path d="M48 40c0-12 7-20 16-20s16 8 16 20" fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round"/>',
        bottle: '<path d="M54 18h20v18l11 12v43H43V48l11-12V18Z" fill="currentColor" opacity=".22"/><path d="M54 18h20v18l11 12v43H43V48l11-12V18Z" fill="none" stroke="currentColor" stroke-width="7" stroke-linejoin="round"/><path d="M55 18h18M52 64h24" stroke="currentColor" stroke-width="7" stroke-linecap="round"/>'
      };

      function ProductIcon({ shape }) {
        return `
          <svg viewBox="0 0 128 112" aria-hidden="true" focusable="false">
            ${iconPaths[shape]}
          </svg>
        `;
      }

      function Header() {
        const navLinks = store.navItems
          .map((item) => `<li><a href="${item.href}">${item.label}</a></li>`)
          .join("");

        return `
          <header class="site-header">
            <div class="page-shell">
              <div class="header-inner">
                <a class="brand" href="#maincontent" aria-label="Luma and Co. home">
                  <span class="brand-mark" aria-hidden="true">LC</span>
                  <span>Luma &amp; Co.</span>
                </a>
                <nav class="primary-nav" aria-label="Primary">
                  <ul>${navLinks}</ul>
                </nav>
                <div class="header-actions">
                  <span class="cart-status" id="cart-count">Bag: 0 items</span>
                  <span class="visually-hidden" id="shopping-status" role="status" aria-live="polite"></span>
                  <a class="button secondary" href="#featured">Shop now</a>
                </div>
              </div>
            </div>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="hero" aria-labelledby="home-heading">
            <div class="hero-panel">
              <div>
                <p class="eyebrow">Spring collection is live</p>
                <h1 id="home-heading">Made for modern everyday living.</h1>
                <p class="hero-copy">
                  Discover refined essentials across apparel, home, wellness, and travel,
                  curated for comfort, longevity, and a more considered routine.
                </p>
                <div class="hero-actions">
                  <a class="button" href="#featured">Shop featured products</a>
                  <a class="text-button" href="#editorial">Read the journal</a>
                </div>
              </div>
              <dl class="hero-metrics">
                <div class="metric"><dt>Dispatch</dt><dd><strong>48h</strong><span>carbon-aware dispatch</span></dd></div>
                <div class="metric"><dt>Customer rating</dt><dd><strong>4.8/5</strong><span>average product rating</span></dd></div>
                <div class="metric"><dt>Member returns</dt><dd><strong>Free</strong><span>returns for members</span></dd></div>
              </dl>
            </div>
            <section class="spotlight-card" aria-labelledby="spotlight-heading">
              <div class="spotlight-visual" aria-hidden="true">
                <div class="bag-shape"></div>
              </div>
              <div class="spotlight-content">
                <p class="eyebrow">Member exclusive</p>
                <h2 id="spotlight-heading">Weekend edit</h2>
                <p>Bundle the Transit Weekender with a travel pouch and receive a $20 reward.</p>
                <a class="button secondary" href="#deals">See current deals</a>
              </div>
            </section>
          </section>
        `;
      }

      function SectionHeader({ eyebrow, title, text, cta, href }) {
        return `
          <div class="section-header">
            <div>
              <p class="eyebrow">${eyebrow}</p>
              <h2>${title}</h2>
              <p>${text}</p>
            </div>
            ${cta ? `<a class="text-button" href="${href}">${cta}</a>` : ""}
          </div>
        `;
      }

      function ProductCard(product) {
        return `
          <article class="card product-card">
            <div class="product-visual" style="--visual-bg: ${product.color}; --visual-ink: ${product.ink};" aria-hidden="true">
              ${ProductIcon(product)}
            </div>
            <div class="product-body">
              <span class="tag">${product.tag}</span>
              <h3><a class="product-title-link" href="${product.href}">${product.name}</a></h3>
              <p class="product-meta">${product.category} · ${product.detail}</p>
              <div class="price-row">
                <span class="price">${product.price}</span>
              </div>
              <button class="button add-to-bag" type="button" data-product="${product.name}" aria-label="Add to bag: ${product.name}">
                Add to bag
              </button>
            </div>
          </article>
        `;
      }

      function FeaturedProducts() {
        return `
          <section class="section" id="featured" aria-labelledby="featured-heading">
            ${SectionHeader({
              eyebrow: "Featured products",
              title: '<span id="featured-heading">Fresh picks for right now</span>',
              text: "Design-led pieces with useful details, gentle materials, and calm colorways.",
              cta: "View all new arrivals",
              href: "#featured"
            })}
            <div class="grid product-grid">
              ${store.products.map(ProductCard).join("")}
            </div>
          </section>
        `;
      }

      function DealCard(deal) {
        return `
          <article class="card deal-card">
            <div class="deal-visual" style="--visual-bg: ${deal.color};">
              <span class="deal-percent">${deal.percent}</span>
            </div>
            <div class="deal-body">
              <h3>${deal.title}</h3>
              <p class="deal-meta">${deal.detail}</p>
              <p><a href="${deal.href}">${deal.cta}</a></p>
            </div>
          </article>
        `;
      }

      function Deals() {
        return `
          <section class="section" id="deals" aria-labelledby="deals-heading">
            ${SectionHeader({
              eyebrow: "Limited-time deals",
              title: '<span id="deals-heading">Savings with a point of view</span>',
              text: "Smart promotions on seasonal essentials, bundle rewards, and high-rated favorites.",
              cta: "Browse every deal",
              href: "#deals"
            })}
            <div class="grid deal-grid">
              ${store.deals.map(DealCard).join("")}
            </div>
          </section>
        `;
      }

      function PromoBand() {
        return `
          <section class="promo-band" id="membership" aria-labelledby="membership-heading">
            <div>
              <p class="eyebrow">Luma Circle</p>
              <h2 id="membership-heading">Join for early drops, free returns, and double-point days.</h2>
              <p>Members get first access to capsule collections and editorial shopping guides.</p>
            </div>
            <a class="button secondary" href="#newsletter">Join free today</a>
          </section>
        `;
      }

      function EditorialCard(article) {
        const featuredClass = article.featured ? " featured" : "";
        return `
          <article class="card editorial-card${featuredClass}">
            <div class="editorial-visual ${article.pattern}" aria-hidden="true"></div>
            <div class="editorial-body">
              <p class="article-meta">${article.meta}</p>
              <h3><a class="editorial-title-link" href="${article.href}">${article.title}</a></h3>
              <p>${article.detail}</p>
              <p><a href="${article.href}">Read article</a></p>
            </div>
          </article>
        `;
      }

      function Editorial() {
        return `
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            ${SectionHeader({
              eyebrow: "Editorial",
              title: '<span id="editorial-heading">Ideas from the Luma journal</span>',
              text: "Practical guides and editor notes to help you choose better, wear longer, and live lighter.",
              cta: "Visit the journal",
              href: "#editorial"
            })}
            <div class="grid editorial-grid">
              ${store.articles.map(EditorialCard).join("")}
            </div>
          </section>
        `;
      }

      function Newsletter() {
        return `
          <section class="newsletter" id="newsletter" aria-labelledby="newsletter-heading">
            <div>
              <p class="eyebrow">Inbox edit</p>
              <h2 id="newsletter-heading">Get the weekly drop</h2>
              <p>One concise email with new arrivals, restocks, deals, and styling notes.</p>
            </div>
            <form class="newsletter-form" id="newsletter-form" novalidate>
              <div class="field">
                <label for="email">Email address (required)</label>
                <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-help email-error">
                <p class="help-text" id="email-help">Required. Example: hello@example.com</p>
                <p class="help-text form-message" id="email-error"></p>
              </div>
              <button class="button" type="submit">Sign up</button>
              <p id="newsletter-status" class="help-text form-message" role="status"></p>
            </form>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer class="site-footer">
            <div class="page-shell footer-inner">
              <p class="footer-note">&copy; 2026 Luma &amp; Co. Thoughtful retail for everyday rituals.</p>
              <nav class="footer-nav" aria-label="Footer">
                <ul>
                  <li><a href="#membership">About</a></li>
                  <li><a href="#deals">Shipping</a></li>
                  <li><a href="#maincontent">Accessibility</a></li>
                  <li><a href="mailto:hello@luma.example">Contact</a></li>
                </ul>
              </nav>
            </div>
          </footer>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="maincontent" class="page-shell" tabindex="-1">
            ${Hero()}
            ${FeaturedProducts()}
            ${Deals()}
            ${PromoBand()}
            ${Editorial()}
            ${Newsletter()}
          </main>
          ${Footer()}
        `;
      }

      function wireInteractions() {
        let bagCount = 0;
        const cartCount = document.querySelector("#cart-count");
        const shoppingStatus = document.querySelector("#shopping-status");
        const emailError = document.querySelector("#email-error");
        const newsletterStatus = document.querySelector("#newsletter-status");

        document.querySelectorAll(".add-to-bag").forEach((button) => {
          button.addEventListener("click", () => {
            bagCount += 1;
            const productName = button.dataset.product;
            cartCount.textContent = `Bag: ${bagCount} ${bagCount === 1 ? "item" : "items"}`;
            shoppingStatus.textContent = `${productName} added to your bag. Bag now has ${bagCount} ${bagCount === 1 ? "item" : "items"}.`;
          });
        });

        document.querySelector("#newsletter-form").addEventListener("submit", (event) => {
          event.preventDefault();
          const email = document.querySelector("#email");

          if (!email.validity.valid) {
            email.setAttribute("aria-invalid", "true");
            emailError.textContent = "Error: Enter a valid email address like hello@example.com.";
            newsletterStatus.textContent = "";
            email.focus();
            return;
          }

          email.removeAttribute("aria-invalid");
          emailError.textContent = "";
          newsletterStatus.textContent = "Thanks. You are signed up for the weekly drop.";
          event.currentTarget.reset();
        });

        document.querySelector("#email").addEventListener("input", (event) => {
          if (event.currentTarget.validity.valid) {
            event.currentTarget.removeAttribute("aria-invalid");
            emailError.textContent = "";
          }
        });
      }

      document.querySelector("#app").innerHTML = App();
      wireInteractions();
    </script>
