           </div>
         `;
       }

       function ProductCard(product) {
         return `
           <article class="card product-card">
             <div class="product-visual" style="--visual-bg: ${product.color}; --visual-ink: ${product.ink};" aria-hidden="true">
               ${ProductIcon(product)}
             </div>
             <div class="product-body">
               <span class="tag">${product.tag}</span>
               <h3><a class="product-title-link" href="${product.href}">${product.name}</a></h3>
               <p class="product-meta">${product.category} · ${product.detail}</p>
               <div class="price-row">
                 <span class="price">${product.price}</span>
               </div>
               <button class="button add-to-bag" type="button" data-product="${product.name}" aria-label="Add to bag: ${product.name}">
                 Add to bag
               </button>
             </div>
           </article>
         `;
       }

       function FeaturedProducts() {
         return `
           <section class="section" id="featured" aria-labelledby="featured-heading">
             ${SectionHeader({
               eyebrow: "Featured products",
               title: '<span id="featured-heading">Fresh picks for right now</span>',
               text: "Design-led pieces with useful details, gentle materials, and calm colorways.",
               cta: "View all new arrivals",
               href: "#featured"
             })}
             <div class="grid product-grid">
               ${store.products.map(ProductCard).join("")}
             </div>
           </section>
         `;
       }

       function DealCard(deal) {
         return `
           <article class="card deal-card">
             <div class="deal-visual" style="--visual-bg: ${deal.color};">
               <span class="deal-percent">${deal.percent}</span>
             </div>
             <div class="deal-body">
               <h3>${deal.title}</h3>
               <p class="deal-meta">${deal.detail}</p>
               <p><a href="${deal.href}">${deal.cta}</a></p>
             </div>
           </article>
         `;
       }

       function Deals() {
         return `
           <section class="section" id="deals" aria-labelledby="deals-heading">
             ${SectionHeader({
               eyebrow: "Limited-time deals",
               title: '<span id="deals-heading">Savings with a point of view</span>',
               text: "Smart promotions on seasonal essentials, bundle rewards, and high-rated favorites.",
               cta: "Browse every deal",
               href: "#deals"
             })}
             <div class="grid deal-grid">
               ${store.deals.map(DealCard).join("")}
             </div>
           </section>
         `;
       }

       function PromoBand() {
         return `
           <section class="promo-band" id="membership" aria-labelledby="membership-heading">
             <div>
               <p class="eyebrow">Luma Circle</p>
               <h2 id="membership-heading">Join for early drops, free returns, and double-point days.</h2>
               <p>Members get first access to capsule collections and editorial shopping guides.</p>
             </div>
             <a class="button secondary" href="#newsletter">Join free today</a>
           </section>
         `;
       }

       function EditorialCard(article) {
         const featuredClass = article.featured ? " featured" : "";
         return `
           <article class="card editorial-card${featuredClass}">
             <div class="editorial-visual ${article.pattern}" aria-hidden="true"></div>
             <div class="editorial-body">
               <p class="article-meta">${article.meta}</p>
               <h3><a class="editorial-title-link" href="${article.href}">${article.title}</a></h3>
               <p>${article.detail}</p>
               <p><a href="${article.href}">Read article</a></p>
             </div>
           </article>
         `;
       }

       function Editorial() {
         return `
           <section class="section" id="editorial" aria-labelledby="editorial-heading">
             ${SectionHeader({
               eyebrow: "Editorial",
               title: '<span id="editorial-heading">Ideas from the Luma journal</span>',
               text: "Practical guides and editor notes to help you choose better, wear longer, and live lighter.",
               cta: "Visit the journal",
               href: "#editorial"
             })}
             <div class="grid editorial-grid">
               ${store.articles.map(EditorialCard).join("")}
             </div>
           </section>
         `;
       }

       function Newsletter() {
         return `
           <section class="newsletter" id="newsletter" aria-labelledby="newsletter-heading">
             <div>
               <p class="eyebrow">Inbox edit</p>
               <h2 id="newsletter-heading">Get the weekly drop</h2>
               <p>One concise email with new arrivals, restocks, deals, and styling notes.</p>
             </div>
             <form class="newsletter-form" id="newsletter-form" novalidate>
               <div class="field">
                 <label for="email">Email address (required)</label>
                 <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-help email-error">
                 <p class="help-text" id="email-help">Required. Example: hello@example.com</p>
                 <p class="help-text form-message" id="email-error"></p>
               </div>
               <button class="button" type="submit">Sign up</button>
               <p id="newsletter-status" class="help-text form-message" role="status"></p>
             </form>
           </section>
         `;
       }

       function Footer() {
         return `
           <footer class="site-footer">
             <div class="page-shell footer-inner">
               <p class="footer-note">&copy; 2026 Luma &amp; Co. Thoughtful retail for everyday rituals.</p>
               <nav class="footer-nav" aria-label="Footer">
                 <ul>
                   <li><a href="#membership">About</a></li>
                   <li><a href="#deals">Shipping</a></li>
                   <li><a href="#maincontent">Accessibility</a></li>
                   <li><a href="mailto:hello@luma.example">Contact</a></li>
                 </ul>
               </nav>
             </div>
           </footer>
         `;
       }

       function App() {
         return `
           ${Header()}
           <main id="maincontent" class="page-shell" tabindex="-1">
             ${Hero()}
             ${FeaturedProducts()}
             ${Deals()}
             ${PromoBand()}
             ${Editorial()}
             ${Newsletter()}
           </main>
           ${Footer()}
         `;
       }

       function wireInteractions() {
         let bagCount = 0;
         const cartCount = document.querySelector("#cart-count");
         const shoppingStatus = document.querySelector("#shopping-status");
         const emailError = document.querySelector("#email-error");
         const newsletterStatus = document.querySelector("#newsletter-status");

         document.querySelectorAll(".add-to-bag").forEach((button) => {
           button.addEventListener("click", () => {
             bagCount += 1;
             const productName = button.dataset.product;
             cartCount.textContent = `Bag: ${bagCount} ${bagCount === 1 ? "item" : "items"}`;
             shoppingStatus.textContent = `${productName} added to your bag. Bag now has ${bagCount} ${bagCount === 1 ? "item" : "items"}.`;
           });
         });

         document.querySelector("#newsletter-form").addEventListener("submit", (event) => {
           event.preventDefault();
           const email = document.querySelector("#email");

           if (!email.validity.valid) {
             email.setAttribute("aria-invalid", "true");
             emailError.textContent = "Error: Enter a valid email address like hello@example.com.";
             newsletterStatus.textContent = "";
             email.focus();
             return;
           }

           email.removeAttribute("aria-invalid");
           emailError.textContent = "";
           newsletterStatus.textContent = "Thanks. You are signed up for the weekly drop.";
           event.currentTarget.reset();
         });

         document.querySelector("#email").addEventListener("input", (event) => {
           if (event.currentTarget.validity.valid) {
             event.currentTarget.removeAttribute("aria-invalid");
             emailError.textContent = "";
           }
         });
       }

       document.querySelector("#app").innerHTML = App();
       wireInteractions();
     </script>
   </body>
 </html>

')
